// 공격 범위 도우미: 오른쪽을 바라볼 때 기준 상대 좌표 (x: 앞쪽 +, y: 아래쪽 +)
function area(x0, x1, y0, y1) {
  const r = [];
  for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) r.push([x, y]);
  return r;
}

// ---------------------------------------------------------------------
//  오퍼레이터
//  cost: 배치 코스트 / redeploy: 재배치(초) / block: 저지 수 / interval: 공격 간격(초)
//  talents: 재능. effect 키 — atk, hp, def(배율), speed(공격 간격 배율), dodge(물리 회피 확률),
//           firstStrike(배치 후 첫 공격 배율), crit({rate, mul}), auraDef({radius, def}: 주변 아군 방어력 +),
//           guard({below, taken}: HP가 below 이하일 때 받는 대미지 배율), lastStand({below, heal}: 1회 회복),
//           focus({step, max}: 같은 적을 연속 공격할수록 방어력 무시 비율 증가),
//           partnerSpeed({speed, partner, partnerSpeed}: 약화된 적 공격 시 공격 간격 배율, 파트너가 편성되면 더 빨라짐),
//           analyze({rate, max, def, res}: 범위 안 적에게 초당 rate씩 「분석」 누적, 1스택당 방어력 -def 비율·마법 저항 -res),
//           deduce({amp, partner, partnerAmp}: 분석 완료된 적이 받는 피해 증가, 파트너의 피해는 추가 증가),
//           listen({step, max}: 같은 아군을 연속 치료할수록 치료량 증가), protect({mul}: 치료 범위 안 아군의 상태 이상 지속시간 배율),
//           proof({hits, res}: 같은 적을 hits회 공격하면 「입증」 — 마법 저항 -res), argue({mul}: 입증된 적에게 추가 마법 피해),
//           houseEdge({vuln, aspd}: 소환물이 저지한 적 취약·저지 중 공격 속도), trustGuest({dp, aspd}: 아군 뱅가드 첫 스킬 코스트·범위 안 뱅가드 공격 속도),
//           mercenary({def, dodge, killAspd, dur, max}: 저지 중 방어·회피, 처치 시 공격 속도 중첩), dailyPay({dp, heal}: 스킬 중 처치 시 코스트, 발동 시 회복)
//           easygoing({def, slow, nullify}: 저지 중 방어력, 저지한 적 공격 간격 배율·공격 무효 확률), reliable({cut, atk}: 주변 가드 물리 피해 감소, 저지한 적을 치는 가드 공격력),
//           relay({dur, atkDown, amp, max}: 공격한 적에게 중계 표식), survive({heal, dur, cut, sp}: 배치당 1회 치명상 무효),
//           principle({aspd, ignore, max, amp}: 같은 적 연속 공격 중첩), strict({cut, atk, dodge}: 저지한 적 피해 감소, 주변 디펜더가 있으면 공격력·회피)
//  tile: 'high' — 직군과 다른 타일에 배치 / groundOnly: 지상 적만 공격 / zone({dur, dps}): 공격할 때 남기는 잔향 지대
//  (연금술사) unluck({dur, fail, failCd}), memory({cut, heal, cd}) / (기수) daily(오늘의 변수), promise({cut, below, shield})
//  스킬: nextZone, aspd, luckAmp, luckAtk, zoneHeal({every, mul}), luckAll, sealLuck, luckDef, luckRes, accident({every, mul, stun}), zoneCut, endStun,
//        dailyMul, dailyWide, dailyMax, endHeal, endGuard({cut, dur})
//  summons: [소환물·장치 정의, …] — charges(배치 가능 횟수, 0이면 스킬로 얻을 때까지 숨김), noDir(방향 선택 없이 설치), aura(주변 8칸 아군 공격 속도 +)
//  (공성사수) blueShot({weight, ignore, step, max}), choice({below, aspd, sp}) / (기능공) echo({res, dur, mul}), courage({cut})
//  스킬: nextSplash, twinShot({mul, blast, radius}), heavyFocus, devAspd, devHits, devAura, devRange, devTargets, fishing({gift, pity, hp}), wave({every, mul, slow, dur}), endCost({hp, aspd, dur})
//  summon: 소환물 정의 (배치하면 카드가 생기고, 배치 인원을 차지하지 않음. 주인이 퇴각하면 함께 퇴각)
//  skills: 스킬 최대 3개. 오퍼레이터 상세 화면에서 고릅니다.
//    sp: 필요 SP / initSp: 시작 SP / duration: 지속(초, 0=즉시, -1=무한)
//    spType: 'time'(자동 회복) | 'attack'(공격 회복) | 'hit'(피격 회복) | 'deploy'(배치 즉시)
//    trigger: 'manual'(직접 발동) | 'auto'(자동 발동)
//    effect 키 — atk/def/interval(배율), targets(동시 공격 수), splash(범위 피해 반경),
//      hits({count, mul}: 공격 1회가 여러 발로), nextHit(다음 공격 배율), charges(효과가 유지되는 공격 횟수),
//      strike({mul, radius, stun}: 즉시 주변 적에게 피해·기절), heal(자기 즉시 회복 비율), regen(초당 회복 비율),
//      allyHeal({mul, radius}: 주변 아군 즉시 회복), allyRegen({mul, radius}: 지속 중 초당 회복),
