//      allyGuard(범위 안 아군이 받는 피해 배율), extraHit({rate, mul}: 확률 추가 타격), proofRate(입증 누적 배율),
//      priority: 'proof'(입증된 적 우선), proofRes(입증된 적 마법 저항 추가 감소), proofBlast(종료 시 입증된 모든 적에게 마법 피해 배율),
