        '다이치는 가끔 무슨 생각을 하는지 모르겠어. ……아니, 나쁜 뜻은 아니야. 그냥…… 늘 비슷한 얼굴이니까. 그래도 오래 지내다 보면 조금씩 알게 되긴 해.',
