      trust100: '다이치는 남의 이야기를 잘 들어. ……그렇다고 자기 의견이 없는 건 아니야. 오히려 한번 결정한 일에는 꽤 완고한 편이지. ……뭐, 그래서 더 상대하기 까다로운 거지만.',
      trust150: '……그 인형? 다이치가 준 거야. 별다른 이유는 없었어. 그냥…… 지나가다가 봤다면서. ……귀엽냐고? ……응. 귀엽긴 해. ……왜, 이상해?',
      trust200: '……다이치랑 사귀기 전에도 자주 같이 있었어. 지금도 크게 달라진 건 없고. ……뭐, 조금은 달라졌을지도 모르지. 예전보다…… 그 녀석이 곁에 있는 게 더 자연스러워졌다고 해야 하나. ……아, 됐어. 이 얘기는 여기까지.',
