      trust200: '저는 테일러의 방식에 동의하지 않습니다. 앞으로도 동의할 생각은 없습니다. ……하지만 그가 자신의 책임을 저버릴 사람이라고 생각하지는 않습니다. 오랜 시간 함께 일하며 확인한 사실입니다. ……그 정도면 충분한 설명이 되었습니까?',
