      select: ['네, 박사님!', '어디로 가면 될까요?'],
      deploy: ['바다가 펼쳐질 거예요.', '……여기라면 괜찮겠죠?'],
      combat: ['흰동가리들아, 부탁해!', '으앗! 저리 가세요!', '파도가 밀려와요!', '……저도 물러서지 않을 거예요!'],
      hard: '우, 우와……! 정말 대단해요! ……그런데 너무 무서웠어요……! 흐아앙, 다행이다……!',
      clear: '끝났나요? ……정말요? 다행이에요! 다들 수고하셨어요!',
      clear2: '……조금 아쉽네요. 그래도 모두 무사히 돌아와서 다행이에요.',
