      base: '와아, 예쁜 곳이네요! ……아, 작은 어항을 놓아도 될까요?',
      touch: '꺄악! ……아, 박사님……! 노, 놀랐잖아요……!',
      trustTouch: '후후, 박사님. 제가 작은 선물을 준비했어요. 조개껍데기로 만든 장식인데…… 받아 주실래요?',
      idle: '……박사님? ……주무시나 봐요. 그럼 조용히…… 꺅! ……아, 제 그림자였어요……! 으으…… 놀랐어…….',
