// 적 그림: img/enemy/<적 id>.png (원작 적 도감 아이콘). 다른 그림을 쓰려면 적마다 image: '경로'를 넣으세요.
for (const [id, e] of Object.entries(ENEMIES)) if (e.image === undefined) e.image = `img/enemy/${id}.png`;

